using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _sut = null!;

    [TestInitialize]
    public void Setup() => _sut = new ShoppingCart();

    // ── AddItem ──────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_IncreasesItemCount()
    {
        _sut.AddItem("SKU-1", 2, 9.99m);

        Assert.AreEqual(1, _sut.ItemCount);
        Assert.AreEqual(19.98m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_TracksEachSeparately()
    {
        _sut.AddItem("A", 1, 10m);
        _sut.AddItem("B", 3, 5m);

        Assert.AreEqual(2, _sut.ItemCount);
        Assert.AreEqual(25m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_AccumulatesQuantityAndUsesLatestPrice()
    {
        _sut.AddItem("SKU-1", 2, 5m);
        _sut.AddItem("SKU-1", 3, 7m);

        Assert.AreEqual(1, _sut.ItemCount);
        // 5 items × $7 = $35
        Assert.AreEqual(35m, _sut.CalculateTotal());
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    [DataRow("", DisplayName = "Empty SKU")]
    [DataRow("   ", DisplayName = "Whitespace SKU")]
    public void AddItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.AddItem(sku!, 1, 10m));
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero quantity")]
    [DataRow(-1, DisplayName = "Negative quantity")]
    public void AddItem_InvalidQuantity_Throws(int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _sut.AddItem("SKU-1", quantity, 10m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _sut.AddItem("SKU-1", 1, -1m));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Succeeds()
    {
        _sut.AddItem("FREE", 2, 0m);

        Assert.AreEqual(1, _sut.ItemCount);
        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    // ── RemoveItem ───────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_DecreasesItemCountAndTotal()
    {
        _sut.AddItem("A", 1, 10m);
        _sut.AddItem("B", 1, 20m);

        _sut.RemoveItem("A");

        Assert.AreEqual(1, _sut.ItemCount);
        Assert.AreEqual(20m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFound()
    {
        var ex = Assert.ThrowsException<KeyNotFoundException>(
            () => _sut.RemoveItem("MISSING"));

        Assert.IsTrue(ex.Message.Contains("MISSING"));
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    [DataRow("", DisplayName = "Empty SKU")]
    public void RemoveItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.RemoveItem(sku!));
    }

    // ── CalculateTotal ───────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _sut.AddItem("A", 2, 15m);  // 30
        _sut.AddItem("B", 1, 7.5m); // 7.50

        Assert.AreEqual(37.5m, _sut.CalculateTotal());
    }

    // ── ApplyCoupon ──────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 90, DisplayName = "10% off")]
    [DataRow("SAVE20", 80, DisplayName = "20% off")]
    [DataRow("HALF", 50, DisplayName = "50% off")]
    public void ApplyCoupon_ValidCode_ReducesTotal(string code, int expectedTotal)
    {
        _sut.AddItem("X", 1, 100m);

        _sut.ApplyCoupon(code);

        Assert.AreEqual((decimal)expectedTotal, _sut.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_AcceptsLowercase()
    {
        _sut.AddItem("X", 1, 100m);

        _sut.ApplyCoupon("save10");

        Assert.AreEqual(90m, _sut.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsArgumentException()
    {
        var ex = Assert.ThrowsException<ArgumentException>(
            () => _sut.ApplyCoupon("BOGUS"));

        Assert.IsTrue(ex.Message.Contains("BOGUS"));
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null code")]
    [DataRow("", DisplayName = "Empty code")]
    public void ApplyCoupon_NullOrEmpty_Throws(string? code)
    {
        Assert.ThrowsException<ArgumentException>(() => _sut.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_ReplacedBySecondCoupon_UsesLatestDiscount()
    {
        _sut.AddItem("X", 1, 100m);
        _sut.ApplyCoupon("SAVE10");
        _sut.ApplyCoupon("SAVE20");

        Assert.AreEqual(80m, _sut.CalculateTotal());
    }

    // ── Combined scenarios ───────────────────────────────────

    [TestMethod]
    public void FullWorkflow_AddRemoveCoupon_ProducesCorrectTotal()
    {
        _sut.AddItem("A", 2, 50m);   // 100
        _sut.AddItem("B", 1, 30m);   // 30
        _sut.RemoveItem("B");         // back to 100
        _sut.ApplyCoupon("SAVE20");   // 20% off → 80

        Assert.AreEqual(80m, _sut.CalculateTotal());
        Assert.AreEqual(1, _sut.ItemCount);
    }
}

